test_cases.assertion_pseudocode:
result = None
try:
    result = load_config()
except ConfigError:
    pass
assert result is None  # no partial config returned

property_tests.invariant_check:
merged = shallow_merge(G, L)
for section in L:
    assert merged[section] == L[section]  # local section exactly preserved
for section in G:
    if section not in L:
        assert merged[section] == G[section]  # global section inherited
    else:
        assert merged[section] != G[section] or G[section] == L[section]  # global section replaced

result = None
try:
    result = load_config()
except ConfigError:
    pass
except Exception as e:
    assert isinstance(e, ConfigError), f'Wrong exception type: {type(e)}'
assert result is None  # no partial config ever returned
